contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets,
        uint256[] memory floorAssetTokenIds
    ) public payable {
        require(maker != address(0), "maker zero");
        require(expiration > block.timestamp, "expiration in past");
        require(duration < 10_000 days, "duration too long");
        require(baseAsset.code.length > 0, "baseAsset not contract");

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 oppositeHash = c.hashOppositeOrder(order);
        uint256 positionId = uint256(oppositeHash);

        bool reverted;
        try c.fillOrder(order, new bytes(0), floorAssetTokenIds) returns (uint256 returnedId) {
            reverted = false;
            assert(returnedId == positionId);
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.ownerOf(positionId) == msg.sender);
            assert(c.positionExpirations(positionId) == block.timestamp + duration);
        }
    }

    receive() external payable {}
}

