contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets,
        bytes memory signature,
        uint256[] memory floorAssetTokenIds
    ) public payable {
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 hash = c.hashOrder(order);

        c.cancel(order);

        bool cancelled = c.cancelledOrders(hash);

        bool reverted;
        require(address(this).balance >= msg.value, "Balance too low");
        try c.fillOrder{value: msg.value}(order, signature, floorAssetTokenIds) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(cancelled && reverted);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets
    ) public payable {
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        C.Order memory flipped = C.Order({
            maker: order.maker,
            isCall: order.isCall,
            isLong: !order.isLong,
            baseAsset: order.baseAsset,
            strike: order.strike,
            premium: order.premium,
            duration: order.duration,
            expiration: order.expiration,
            nonce: order.nonce,
            whitelist: order.whitelist,
            floorTokens: order.floorTokens,
            erc20Assets: order.erc20Assets,
            erc721Assets: order.erc721Assets
        });

        bytes32 originalHash = c.hashOrder(order);
        bytes32 flippedHash = c.hashOrder(flipped);
        bytes32 oppositeHash = c.hashOppositeOrder(order);

        assert(oppositeHash == flippedHash && (originalHash != oppositeHash || isLong != !order.isLong));
    }
}

