contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 seed) public payable {
        // Build a valid order from the parameter. The maker is this test contract,
        // so the signature check is bypassed by SignatureChecker (ERC-1271 fallback
        // accepts an empty signature from a contract that returns the magic value).
        C.Order memory order = C.Order({
            maker: address(this),
            isCall: false,
            isLong: false,
            baseAsset: address(0x2222),
            strike: 0,
            premium: 0,
            duration: seed % 10_000 days,
            expiration: type(uint256).max,
            nonce: seed,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        require(order.duration < 10_000 days, "duration out of range");

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);

        uint256 positionId = c.fillOrder(order, "", new uint256[](0));

        // The taker position gets the opposite-order hash, the maker position
        // gets the order hash, and the two are distinct.
        assert(
            positionId == uint256(oppositeHash) &&
            c.ownerOf(uint256(orderHash)) == address(this) &&
            c.ownerOf(positionId) == address(this) &&
            positionId != uint256(orderHash)
        );
    }

    receive() external payable {}

    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(C.Order memory order, bytes calldata signature, uint256[] memory floorAssetTokenIds) public payable {
        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);

        require(!c.cancelledOrders(orderHash), "order already cancelled");
        require(order.whitelist.length == 0, "whitelist not empty");
        require(order.duration < 10_000 days, "duration too long");
        require(block.timestamp < order.expiration, "order expired");
        require(order.baseAsset.code.length > 0, "baseAsset not contract");
        require(msg.value == 0 || order.baseAsset == c.weth(), "eth requires weth baseAsset");
        if (order.isCall && order.isLong) {
            require(floorAssetTokenIds.length == order.floorTokens.length, "wrong floor tokenIds length");
        } else {
            require(floorAssetTokenIds.length == 0, "invalid floor tokens length");
        }

        bool ok;
        try c.fillOrder{value: msg.value}(order, signature, floorAssetTokenIds) {
            ok = true;
        } catch {
            ok = false;
        }

        address makerOwner = c.ownerOf(uint256(orderHash));
        address fillerOwner = c.ownerOf(uint256(oppositeHash));

        assert(!ok || (makerOwner == order.maker && fillerOwner == msg.sender));
    }

    receive() external payable {}
}

